-- 0019_gate_template_scope — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- Vlad, 14 Nov: gates are configured by a director or above, not universal. A template applies to a scope, and a
-- project takes the most specific one: its own explicit template (site.gate_template_id), else programme +
-- country, programme, client + country, client, else the base template (no client).
ALTER TABLE gate_template ALTER COLUMN client_id DROP NOT NULL;
ALTER TABLE gate_template ADD COLUMN country_code text CHECK (country_code ~ '^[A-Z]{2}$');
ALTER TABLE gate_template ADD COLUMN updated_by uuid;
ALTER TABLE gate_template ADD CONSTRAINT gate_template_scope CHECK (programme_id IS NULL OR client_id IS NOT NULL);
-- One active template per scope (nulls compared as equal: the base template is unique too).
CREATE UNIQUE INDEX gate_template_active_scope ON gate_template (
  coalesce(client_id, '00000000-0000-0000-0000-000000000000'::uuid),
  coalesce(programme_id, '00000000-0000-0000-0000-000000000000'::uuid),
  coalesce(country_code, '')
) WHERE archived_at IS NULL;
